package android.content;import java.util.*;public class Intent {public static final String ACTION_SEND="send",ACTION_SEND_MULTIPLE="send-multiple",EXTRA_STREAM="stream",EXTRA_TEXT="text",EXTRA_SUBJECT="subject";public String action,type;public Class<?> component;public final Map<String,Object> extras=new HashMap<>();public Intent(){}public Intent(String a){action=a;}public Intent(Context c,Class<?> cls){component=cls;}public Intent setAction(String s){action=s;return this;}public String getAction(){return action;}public Intent setType(String s){type=s;return this;}public String getType(){return type;}public Intent putExtra(String k,Object v){extras.put(k,v);return this;}@SuppressWarnings("unchecked") public <T>T getParcelableExtra(String k){return(T)extras.get(k);}@SuppressWarnings("unchecked") public <T>ArrayList<T> getParcelableArrayListExtra(String k){return(ArrayList<T>)extras.get(k);}public String getStringExtra(String k){return(String)extras.get(k);}public CharSequence getCharSequenceExtra(String k){return(CharSequence)extras.get(k);}}
